#!/usr/bin/env node
'use strict';

// Compiles every art/<category>/<name>.txt into lib/catalog.js, and generates the
// ESM entry point, the TypeScript name declarations and GALLERY.md from the same list.
// Run with --check to verify the generated files are up to date (used in CI).

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const ART_DIR = path.join(ROOT, 'art');
const LIB_DIR = path.join(ROOT, 'lib');
const NAME_RE = /^[a-z][a-z0-9]*$/;

function parseArtFile(file) {
  const source = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  const meta = {};
  let body = source;

  if (source.startsWith('---\n')) {
    const end = source.indexOf('\n---\n', 4);
    if (end === -1) throw new Error(`${file}: unterminated frontmatter`);
    for (const line of source.slice(4, end).split('\n')) {
      const match = line.match(/^(\w+):\s*(.*)$/);
      if (!match) throw new Error(`${file}: invalid frontmatter line "${line}"`);
      meta[match[1]] = match[2].trim();
    }
    body = source.slice(end + 5);
  }

  if (body.includes('\t')) throw new Error(`${file}: tabs are not allowed, use spaces`);
  if (/[^\x20-\x7e\n]/.test(body)) throw new Error(`${file}: only printable ASCII is allowed`);

  const lines = body.split('\n').map((line) => line.replace(/\s+$/, ''));
  while (lines.length && !lines[0].trim()) lines.shift();
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
  if (!lines.length) throw new Error(`${file}: empty art`);

  const indent = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)[0].length));
  return { meta, art: lines.map((l) => l.slice(indent)).join('\n') };
}

function collect() {
  const entries = [];
  const seen = new Map();
  for (const category of fs.readdirSync(ART_DIR).sort()) {
    const dir = path.join(ART_DIR, category);
    if (!fs.statSync(dir).isDirectory()) continue;
    for (const file of fs.readdirSync(dir).sort()) {
      if (!file.endsWith('.txt')) continue;
      const name = file.slice(0, -4);
      if (!NAME_RE.test(name)) throw new Error(`${category}/${file}: names must be lowercase alphanumeric`);
      if (seen.has(name)) throw new Error(`"${name}" exists in both ${seen.get(name)} and ${category}`);
      seen.set(name, category);

      const { meta, art } = parseArtFile(path.join(dir, file));
      const entry = {
        name,
        category,
        tags: meta.tags ? meta.tags.split(',').map((t) => t.trim()).filter(Boolean) : [],
        artist: meta.artist || null,
        art,
      };
      if (meta.tail) entry.tail = Number(meta.tail);
      entries.push(entry);
    }
  }
  return entries;
}

const HEADER = '// This file is generated by scripts/build.js from the art/ folder. Do not edit it by hand.\n';

function renderCatalog(entries) {
  return { 'lib/catalog.js': `${HEADER}'use strict';\n\nmodule.exports = ${JSON.stringify(entries, null, 2)};\n` };
}

// Needs lib/catalog.js to exist, because it loads the API to list its exports.
function renderEntryPoints(entries) {
  const names = entries.map((e) => e.name);
  const categories = [...new Set(entries.map((e) => e.category))];
  const union = (items) => items.map((n) => `  | '${n}'`).join('\n');

  return {
    'lib/index.mjs':
      `${HEADER}import lib from './index.js';\n\n` +
      `export default lib;\n\n` +
      `export const {\n${Object.keys(require(path.join(LIB_DIR, 'api.js')))
        .concat(names)
        .map((n) => `  ${n},`)
        .join('\n')}\n} = lib;\n`,
    'lib/names.d.ts':
      `${HEADER}\nexport type ArtName =\n${union(names)};\n\n` +
      `export type Category =\n${union(categories)};\n`,
    'lib/index.d.ts':
      `${HEADER}\nimport type { ArtFunction } from './api';\n\n` +
      `export * from './api';\nexport type { ArtName, Category } from './names';\n\n` +
      names.map((n) => `export declare const ${n}: ArtFunction;`).join('\n') +
      `\n`,
  };
}

function renderGallery(entries) {
  const categories = [...new Set(entries.map((e) => e.category))];
  const anchor = (c) => `#${c}`;
  const sections = categories.map((category) => {
    const items = entries.filter((e) => e.category === category);
    return [
      `## ${category[0].toUpperCase()}${category.slice(1)}`,
      '',
      ...items.map((e) => {
        const credit = e.artist && e.artist !== 'draw-ascii' ? ` — art by ${e.artist}` : '';
        return `### \`${e.name}\`${credit}\n\n\`\`\`text\n${e.art}\n\`\`\`\n`;
      }),
    ].join('\n');
  });
  return {
    'GALLERY.md': [
      '<!-- Generated by scripts/build.js. Do not edit by hand. -->',
      '# Gallery',
      '',
      `All ${entries.length} drawings included in draw-ascii, by category.`,
      '',
      categories.map((c) => `[${c}](${anchor(c)}) (${entries.filter((e) => e.category === c).length})`).join(' · '),
      '',
      ...sections,
    ].join('\n'),
  };
}

function main() {
  const entries = collect();
  const check = process.argv.includes('--check');
  const stale = [];

  const emit = (files) => {
    for (const [file, content] of Object.entries(files)) {
      const target = path.join(ROOT, file);
      const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
      if (current === content) continue;
      if (check) stale.push(file);
      else fs.writeFileSync(target, content);
    }
  };

  emit(renderCatalog(entries));
  emit(renderEntryPoints(entries));
  emit(renderGallery(entries));

  if (stale.length) {
    console.error(`Generated files are out of date: ${stale.join(', ')}. Run "npm run build".`);
    process.exit(1);
  }
}

main();
